function safePath(root,parts){let node=root;for(const p of parts){check((typeof p==='string'||Number.isInteger(p))&&!['__proto__','constructor','prototype'].includes(String(p))&&node&&Object.hasOwn(node,p),'Invalid change path.');node=node[p];}return node;}
