async function fetchAssets(club,hashes,assets,route,stage){for(const hash of hashes){if(assets.has(hash))continue;let offset=0,size=null,chunks=[];do{const r=await club.request(route(hash,offset));check(r.hash===hash&&r.offset===offset&&Number.isSafeInteger(r.size)&&r.size>0&&r.size<=28*CHUNK&&(size===null||size===r.size),'Invalid attachment chunk.');const bytes=Buffer.from(r.data,'base64');check(bytes.length>0&&bytes.length<=CHUNK&&offset+bytes.length<=r.size,'Invalid attachment length.');size=r.size;chunks.push(bytes);offset+=bytes.length;}while(offset<size);const value=Buffer.concat(chunks).toString('utf8');check(F.hash(value)===hash,'Attachment checksum mismatch.');const meta=S.stageAsset(stage.file,hash,value);assets.set(hash,lazy.asset(stage.file,meta));}}
